codingLevel3Id = json\retrieve($response, 'assigned_codes.0.coding_level_3_id');
autoCodingExplanation = json\retrieve($response, 'assigned_codes.0.explanation');
$codingConfidenceAggregate = json\retrieve($response, 'assigned_codes.0.confidence_aggregate');

if ($codingConfidenceAggregate == null || $codingConfidenceAggregate < 0.80) {
    autoCodingConfidence = 'Confidence too low to determine coding';
    autoCodingStatus = 'human_review_required';
} else {
    autoCodingStatus = 'completed';
